function canMakeSubsequence(str1, str2) {
  const n = str1.length;
  const isSub = (s, t) => {
    let k = 0;
    for (const ch of s) if (k < t.length && ch === t[k]) k++;
    return k === t.length;
  };
  for (let mask = 0; mask < (1 << n); mask++) {
    let built = '';
    for (let i = 0; i < n; i++) {
      const code = str1.charCodeAt(i) - 97;
      built += String.fromCharCode(97 + ((mask >> i) & 1 ? (code + 1) % 26 : code));
    }
    if (isSub(built, str2)) return true;
  }
  return false;
}

