function generate(rand, size) {
  const letters = size === 'large' ? 'abcdefghijklmnopqrstuvwxyz' : 'abcyz';
  const pick = () => letters[Math.floor(rand() * letters.length)];
  const n = size === 'large' ? 5000 + Math.floor(rand() * 5001) : 1 + Math.floor(rand() * 8);
  let str1 = '';
  for (let i = 0; i < n; i++) str1 += pick();
  let str2 = '';
  if (rand() < 0.5) {
    // Build str2 from a subsequence of str1 with some letters advanced, so the answer is often true.
    const keep = size === 'large' ? 0.3 + rand() * 0.6 : 0.6;
    for (let i = 0; i < n; i++) {
      if (rand() < keep) {
        const code = str1.charCodeAt(i) - 97;
        str2 += String.fromCharCode(97 + (rand() < 0.5 ? (code + 1) % 26 : code));
      }
    }
    if (str2.length > 0 && rand() < 0.3) {
      const at = Math.floor(rand() * str2.length);
      str2 = str2.slice(0, at) + pick() + str2.slice(at + 1);
    }
  }
  if (str2.length === 0) {
    const m = size === 'large' ? 1 + Math.floor(rand() * 3000) : 1 + Math.floor(rand() * 5);
    for (let i = 0; i < m; i++) str2 += pick();
  }
  return [str1, str2];
}
